// Self-hosted via @fontsource — no build-time Google Fonts fetch.
import "@fontsource/inter";
import "@fontsource/noto-sans-kr";

export const inter = { variable: "" };
export const notoSansKR = { variable: "" };

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Direction-aware clip-path reveal.
 *
 * Attach the returned ref to a block you want wiped in by a hard geometric
 * cut (the brutalist equivalent of a fade). When the block enters the
 * viewport, `is-revealed` is added to it; `styles.css` drives the
 * inset/polygon clip from `--rave-reveal-dir`. The reveal happens once and
 * the observer disconnects — a section does not get to re-wipe every time
 * it scrolls back into frame.
 *
 * No-JS / SSR: the page ships already visible (`rave-reveal` with no
 * `rave-js` ancestor is static, clip-path: none). The pre-reveal hidden
 * state is gated behind `.rave-js .rave-reveal` so the SSR markup is the
 * completed flyer.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    // Reduced motion: leave the SSR-visible state alone. No wipe.
    if (reduced) return;

    const io = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-revealed");
            io.unobserve(entry.target);
          }
        }
      },
      { rootMargin: "-8% 0px -8% 0px", threshold: 0.12 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

"use client";

import { useEffect, useRef, useState } from "react";
import "./styles.css";
import { inter, notoSansKR } from "./fonts";
import { useReveal } from "./hooks/useReveal";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";

/**
 * WIDGET — 공간 글래스 대시보드, visionOS 스타일. A constellation of glass
 * dashboard widgets floating in depth over a gradient. Where HANJI SLATE is a
 * single e-ink device exploding, WIDGET is spatial depth — widgets float
 * toward the pointer at different layers. Pure code.
 */
type Mode = "morning" | "focus";

export default function WidgetPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const stageRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useReveal<HTMLDivElement>();
  const [mode, setMode] = useState<Mode>("morning");

  useEffect(() => {
    rootRef.current?.classList.add("widget-js");
    window.parent?.postMessage({ type: "oneshot:ready", slug: "widget" }, "*");

    if (reduced) return;
    const stage = stageRef.current;
    if (!stage) return;
    const onMove = (ev: PointerEvent) => {
      const rect = stage.getBoundingClientRect();
      const x = (ev.clientX - rect.left) / rect.width - 0.5;
      const y = (ev.clientY - rect.top) / rect.height - 0.5;
      stage.style.setProperty("--widget-px", x.toFixed(3));
      stage.style.setProperty("--widget-py", y.toFixed(3));
    };
    window.addEventListener("pointermove", onMove, { passive: true });
    return () => window.removeEventListener("pointermove", onMove);
  }, [reduced]);

  return (
    <div
      ref={rootRef}
      className={`${inter.variable} ${notoSansKR.variable} widget-root`}
      data-mode={mode}
    >
      <div ref={revealRef} className="widget-doc">
        <header className="widget-hero" data-reveal="">
          <p className="widget-kicker">
            <span lang="ko">공간 대시보드</span> · SPATIAL DASHBOARD
          </p>
          <h1 className="widget-title">
            WIDGET <span lang="ko">위젯</span>
          </h1>
          <p className="widget-sub" data-reveal="">
            <span lang="ko">깊이 속에 떠 있는 위젯들.</span> Widgets that float
            in depth.
          </p>
        </header>

        <section className="widget-stage-section">
          <div className="widget-mode-toggle" data-reveal="">
            <button
              type="button"
              className={`widget-mode-btn ${mode === "morning" ? "is-active" : ""}`}
              onClick={() => setMode("morning")}
            >
              <span lang="ko">아침</span> Morning
            </button>
            <button
              type="button"
              className={`widget-mode-btn ${mode === "focus" ? "is-active" : ""}`}
              onClick={() => setMode("focus")}
            >
              <span lang="ko">집중</span> Focus
            </button>
          </div>

          <div className="widget-stage" ref={stageRef} data-reveal="">
            <div className="widget-card widget-card--weather" data-depth="3">
              <p className="widget-card__label">
                <span lang="ko">날씨</span> Weather
              </p>
              <p className="widget-card__value">21°</p>
              <p className="widget-card__sub">서울 · 맑음</p>
            </div>
            <div className="widget-card widget-card--calendar" data-depth="2">
              <p className="widget-card__label">
                <span lang="ko">오늘</span> Today
              </p>
              <p className="widget-card__value">3</p>
              <p className="widget-card__sub">
                <span lang="ko">회의</span> meetings
              </p>
            </div>
            <div className="widget-card widget-card--chart" data-depth="1">
              <p className="widget-card__label">
                <span lang="ko">주간 완료</span> Weekly done
              </p>
              <div className="widget-card__bars">
                {[40, 65, 30, 80, 55, 90, 45].map((h, i) => (
                  <span key={i} className="widget-bar" style={{ height: `${h}%` }} />
                ))}
              </div>
            </div>
            <div className="widget-card widget-card--music" data-depth="2">
              <p className="widget-card__label">
                <span lang="ko">재생 중</span> Now playing
              </p>
              <p className="widget-card__value-small">새벽 녹음</p>
              <p className="widget-card__sub">EP.044</p>
            </div>
          </div>
        </section>

        <footer className="widget-foot" data-reveal="">
          <p>
            © 2026 WIDGET · <span lang="ko">공간 OS</span> · MIT
          </p>
          <p>
            <span lang="ko">전부 코드로 그렸다 — 이미지 없음.</span> drawn
            entirely in code — no images.
          </p>
        </footer>
      </div>
    </div>
  );
}

/* ==========================================================================
   WIDGET 위젯 — spatial glass dashboard · visionOS style
   bento-product · depth gradient / glass widgets / iris accent
   Scoped by convention to .widget-root; classes prefixed widget-.
   Crafted to the gallery glass-futurism benchmark (see CRAFT-STANDARDS.md).
   ========================================================================== */

.widget-root {
  /* ---- Depth + glass surfaces -----------------------------------------
     Contrast ratios verified against the depth gradient ground
     (#1a1f3a → #2d1f4a, treated as ~#241f3f for measurement).             */
  --w-depth-1:        #1a1f3a;  /* indigo-night — ground top               */
  --w-depth-2:        #2d1f4a;  /* violet-night — ground bottom            */
  --w-glass:          rgba(255, 255, 255, 0.08);   /* glass surface alpha   */
  --w-glass-deep:     rgba(255, 255, 255, 0.12);   /* hover/active lift     */
  --w-glass-border:   rgba(255, 255, 255, 0.15);   /* hairline edge         */
  --w-glass-edge:     rgba(255, 255, 255, 0.20);   /* inner light facet     */
  --w-iris:           #6366f1;  /* indigo-500 · on ground 2.3:1 — large/
                                   decorative only; never body text          */
  --w-iris-bright:    #818cf8;  /* indigo-400 · on ground 3.4:1 — large     */
  --w-iris-soft:      rgba(99, 102, 241, 0.30);
  --w-text:           #f0f0ff;  /* paper-violet · on ground 14.6:1 (AAA)   */
  --w-text-dim:       #a0a0c0;  /* mute-violet  · on ground  7.0:1 (AAA)   */

  --w-font-sans:  "Inter", sans-serif;
  --w-font-kr:    "Noto Sans KR", sans-serif;
  --w-font-stack: "Inter", "Noto Sans KR", sans-serif;

  /* ---- Intent-separated easing curves --------------------------------
     Never default ease/linear; never `transition: all` (see std §1, §7).   */
  --w-ease-reveal: cubic-bezier(0.16, 1, 0.3, 1);   /* entry / reveal       */
  --w-ease-hover:  cubic-bezier(0.25, 1, 0.5, 1);   /* hover / scrub        */
  --w-ease-back:   cubic-bezier(0.34, 1.56, 0.64, 1);/* press micro-bounce  */
  /* Legacy alias kept for any legacy reference. */
  --w-ease: var(--w-ease-reveal);

  /* ---- 4px baseline spacing scale ------------------------------------ */
  --w-sp-1: 0.25rem;  /*  4px */
  --w-sp-2: 0.5rem;   /*  8px */
  --w-sp-3: 0.75rem;  /* 12px */
  --w-sp-4: 1rem;     /* 16px */
  --w-sp-5: 1.25rem;  /* 20px */
  --w-sp-6: 1.5rem;   /* 24px */
  --w-sp-8: 2rem;     /* 32px */
  --w-sp-10: 2.5rem;  /* 40px */
  --w-sp-12: 3rem;    /* 48px */

  /* ---- Multi-layer glass shadow (ambient + key + contact) ------------- */
  --w-shadow-card:
    inset 0 1px 0  rgba(255, 255, 255, 0.10),   /* top facet — bevel        */
    0 1px 2px      rgba(0, 0, 0, 0.30),          /* ambient — contact        */
    0 12px 28px    rgba(0, 0, 0, 0.40),          /* key — primary cast       */
    0 32px 64px    rgba(0, 0, 0, 0.32);          /* contact — far diffusion  */
  --w-shadow-card-lift:
    inset 0 1px 0  rgba(255, 255, 255, 0.14),
    0 1px 2px      rgba(0, 0, 0, 0.34),
    0 18px 36px    rgba(99, 102, 241, 0.20),
    0 40px 80px    rgba(0, 0, 0, 0.40);

  position: relative;
  min-height: 100vh;
  background: linear-gradient(135deg, var(--w-depth-1) 0%, var(--w-depth-2) 100%);
  color: var(--w-text);
  font-family: var(--w-font-stack);
  font-weight: 400;
  font-size: clamp(15px, 0.5vw + 13px, 17px);
  line-height: 1.6;
  letter-spacing: -0.011em;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overflow-x: hidden;
  overflow-x: clip;
}

/* Aurora light field — two slow iris blooms drifting behind the glass, the
   ambient light of a spatial OS. Pure CSS, paused under reduced motion. */
.widget-root::before {
  content: "";
  position: fixed;
  inset: -10%;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(40% 40% at 25% 30%, rgba(99,102,241,0.22), transparent 60%),
    radial-gradient(45% 45% at 78% 70%, rgba(168,85,247,0.18), transparent 60%);
  filter: blur(20px);
  animation: widget-aurora 24s var(--w-ease-hover) infinite alternate;
}
@keyframes widget-aurora {
  to { transform: translate3d(3%, -2%, 0) scale(1.06); }
}
@media (prefers-reduced-motion: reduce) {
  .widget-root::before { animation: none; }
}
.widget-doc { position: relative; z-index: 1; }

/* Korean needs its own metrics — Hangul never gets tracking fanned out. */
.widget-root :lang(ko) {
  font-family: var(--w-font-kr);
  letter-spacing: 0;
  line-height: 1.9;
  word-break: keep-all;
  word-wrap: break-word;
}
.widget-root ::selection { background: var(--w-iris); color: #fff; }
.widget-root :focus-visible {
  outline: 2px solid var(--w-iris-bright);
  outline-offset: 4px;
  border-radius: 2px;
}

.widget-js [data-reveal] {
  opacity: 0;
  transform: translateY(20px);
  transition:
    opacity 800ms var(--w-ease-reveal),
    transform 800ms var(--w-ease-reveal);
}
.widget-js [data-reveal].is-visible { opacity: 1; transform: none; }
@media (prefers-reduced-motion: reduce) {
  .widget-js [data-reveal] { opacity: 1; transform: none; transition: none; }
}

/* ==========================================================================
   Hero — the spatial sign-in
   ========================================================================== */
.widget-hero {
  padding:
    clamp(80px, 16vh, 140px) clamp(20px, 5vw, 60px) clamp(40px, 8vh, 60px);
  text-align: center;
}
.widget-kicker {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--w-iris-bright);
  margin: 0 0 var(--w-sp-6);
  text-wrap: pretty;
}
.widget-title {
  font-weight: 700;
  font-size: clamp(3rem, 10vw, 6rem);
  line-height: 1;
  letter-spacing: -0.04em;          /* display tracking — major glyph run  */
  margin: 0 0 var(--w-sp-4);
  text-wrap: balance;
}
.widget-title :lang(ko) {
  font-size: 0.5em;
  color: var(--w-iris-bright);
  letter-spacing: 0;
}
.widget-sub {
  color: var(--w-text-dim);
  margin: 0;
  text-wrap: pretty;
}

/* ==========================================================================
   Mode toggle — pill switch
   ========================================================================== */
.widget-stage-section {
  padding: clamp(40px, 8vh, 80px) clamp(20px, 5vw, 60px);
}
.widget-mode-toggle {
  display: flex;
  gap: var(--w-sp-2);
  justify-content: center;
  margin: 0 auto var(--w-sp-12);
}
.widget-mode-btn {
  background: var(--w-glass);
  border: 1px solid var(--w-glass-border);
  color: var(--w-text-dim);
  padding: var(--w-sp-3) var(--w-sp-6);
  border-radius: 100px;
  font-family: var(--w-font-sans);
  font-size: 0.85rem;
  letter-spacing: -0.011em;
  cursor: pointer;
  -webkit-backdrop-filter: blur(12px) saturate(140%);
  backdrop-filter: blur(12px) saturate(140%);
  /* Individual properties — NEVER `transition: all`. */
  transition:
    background-color 200ms var(--w-ease-hover),
    border-color     200ms var(--w-ease-hover),
    color            200ms var(--w-ease-hover),
    transform        150ms var(--w-ease-back);
}
.widget-mode-btn.is-active {
  background: var(--w-iris);
  border-color: var(--w-iris);
  color: #fff;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.25),
    0 6px 18px var(--w-iris-soft);
}
.widget-mode-btn:hover:not(.is-active) {
  border-color: var(--w-iris-soft);
  color: var(--w-text);
  transform: translateY(-1px);
}
.widget-mode-btn:focus-visible {
  outline-offset: 6px;
}
.widget-mode-btn:active {
  transform: translateY(0) scale(0.98);
}

/* ==========================================================================
   Stage — the floating widgets
   Depth parallax (rotateY/rotateX by layer) is preserved; a contact
   drop-shadow on each card now grounds it in space, so the float reads as
   suspension rather than flat translateZ.
   ========================================================================== */
.widget-stage {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--w-sp-5);
  max-width: 900px;
  margin: 0 auto;
  perspective: 1000px;
  perspective-origin: 50% 40%;
  --widget-px: 0;
  --widget-py: 0;
}

.widget-card {
  position: relative;
  background: var(--w-glass);
  border: 1px solid var(--w-glass-border);
  border-radius: 20px;
  padding: var(--w-sp-7, 28px) var(--w-sp-6);
  -webkit-backdrop-filter: blur(20px) saturate(160%);
  backdrop-filter: blur(20px) saturate(160%);
  box-shadow: var(--w-shadow-card);
  /* Contact shadow under each card — drop-shadow grounds the floating
     glass, distinct from the box-shadow cast. */
  filter: drop-shadow(0 24px 32px rgba(0, 0, 0, 0.32));
  /* Individual property transitions — color, border, shadow change on
     hover; the parallax transform runs on the scrub curve. */
  transition:
    background-color 300ms var(--w-ease-hover),
    border-color     300ms var(--w-ease-hover),
    box-shadow       300ms var(--w-ease-hover),
    transform        400ms var(--w-ease-hover);
  transform: rotateY(calc(var(--widget-px) * 5deg))
             rotateX(calc(var(--widget-py) * -5deg));
  transform-style: preserve-3d;
}
.widget-card[data-depth="3"] {
  transform: rotateY(calc(var(--widget-px) * 9deg))
             rotateX(calc(var(--widget-py) * -9deg))
             translateZ(20px);
}
.widget-card[data-depth="2"] {
  transform: rotateY(calc(var(--widget-px) * 6deg))
             rotateX(calc(var(--widget-py) * -6deg))
             translateZ(10px);
}
.widget-card[data-depth="1"] {
  transform: rotateY(calc(var(--widget-px) * 3deg))
             rotateX(calc(var(--widget-py) * -3deg));
}
.widget-card:hover {
  background-color: var(--w-glass-deep);
  border-color: var(--w-glass-edge);
  box-shadow: var(--w-shadow-card-lift);
}
@media (prefers-reduced-motion: reduce) {
  .widget-card,
  .widget-card[data-depth="3"],
  .widget-card[data-depth="2"],
  .widget-card[data-depth="1"] {
    transform: none;
    transition:
      background-color 200ms var(--w-ease-hover),
      border-color     200ms var(--w-ease-hover),
      box-shadow       200ms var(--w-ease-hover);
  }
}

.widget-card__label {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--w-text-dim);
  margin: 0 0 var(--w-sp-3);
}
.widget-card__value {
  font-size: clamp(2rem, 5vw, 3rem);
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.03em;          /* large display numeral tracking      */
  color: var(--w-text);
  margin: 0 0 var(--w-sp-2);
  font-variant-numeric: tabular-nums;
}
.widget-card__value-small {
  font-size: 1.2rem;
  font-weight: 600;
  letter-spacing: -0.02em;
  margin: 0 0 var(--w-sp-1);
}
.widget-card__sub {
  font-size: 0.8rem;
  color: var(--w-text-dim);
  margin: 0;
  text-wrap: pretty;
}

/* Chart bars — gradient phosphor */
.widget-card__bars {
  display: flex;
  align-items: flex-end;
  gap: 6px;
  height: 60px;
  margin-top: var(--w-sp-3);
}
.widget-bar {
  flex: 1;
  background: linear-gradient(180deg, var(--w-iris-bright) 0%, var(--w-iris) 60%, var(--w-iris-soft) 100%);
  border-radius: 3px 3px 0 0;
  min-height: 8px;
  box-shadow:
    0 0 1px rgba(255, 255, 255, 0.20),
    0 0 8px var(--w-iris-soft);
}

/* ==========================================================================
   Footer
   ========================================================================== */
.widget-foot {
  padding: clamp(48px, 10vh, 80px) clamp(20px, 5vw, 60px);
  color: var(--w-text-dim);
  font-size: 0.8rem;
  text-align: center;
  text-wrap: pretty;
}
.widget-foot p { margin: 0 0 var(--w-sp-2); }

/* ==========================================================================
   Responsive — honest at 360px, composed at 1440px+
   ========================================================================== */
@media (max-width: 720px) {
  .widget-hero { padding-bottom: var(--w-sp-8); }
  .widget-title { font-size: clamp(2.4rem, 12vw, 4rem); }
  .widget-stage {
    grid-template-columns: 1fr;
    gap: var(--w-sp-4);
    perspective: 800px;
  }
  .widget-card { padding: var(--w-sp-5) var(--w-sp-5); border-radius: 16px; }
  .widget-mode-toggle {
    flex-wrap: wrap;
    margin-bottom: var(--w-sp-8);
  }
}

@media (max-width: 900px) {
  .widget-stage {
    grid-template-columns: repeat(2, 1fr);
  }
  /* On smaller screens, flatten the depth parallax so the cards stay
     legible — suspension becomes a subtle tilt rather than a yaw. */
  .widget-card[data-depth="3"] {
    transform: rotateY(calc(var(--widget-px) * 5deg))
               rotateX(calc(var(--widget-py) * -5deg))
               translateZ(12px);
  }
  .widget-card[data-depth="2"] {
    transform: rotateY(calc(var(--widget-px) * 4deg))
               rotateX(calc(var(--widget-py) * -4deg))
               translateZ(6px);
  }
}

@media (min-width: 1200px) {
  /* On wide screens, let the dashboard breathe and the depth expand. */
  .widget-stage {
    max-width: 1080px;
    perspective: 1200px;
    gap: var(--w-sp-6);
  }
  .widget-card { padding: var(--w-sp-8) var(--w-sp-7, 32px); }
}
